// ── ABSTRACT CLASS: shared state + template ──────────────────────────────
abstract class Shape {
    private final String color;              // instance field — only abstract classes can hold this

    Shape(String color) {                    // constructor — interfaces have none
        this.color = color;
    }

    String getColor() { return color; }      // concrete shared method

    abstract double area();                  // each subclass must provide this
}

// ── INTERFACES: CAN-DO capabilities ──────────────────────────────────────
interface Drawable {
    void draw();                             // abstract method
    default void render() { draw(); }        // Java 8 default method — has a body
}

interface Resizable {
    void resize(double factor);
}

// Interface constants: implicitly public static final
interface Config {
    int MAX_SIDES = 100;   // same as: public static final int MAX_SIDES = 100;
    // int count;          // ILLEGAL: no uninitialized fields in interfaces
}

// ── ONE CLASS: extends ONE abstract class, implements MANY interfaces ─────
class Circle extends Shape implements Drawable, Resizable, Config {
    private double radius;

    Circle(String color, double radius) {
        super(color);                        // abstract class constructor called
        this.radius = radius;
    }

    @Override
    public double area() {
        return Math.PI * radius * radius;
    }

    @Override
    public void draw() {
        System.out.println("Drawing " + getColor() + " circle, area=" + area());
    }

    @Override
    public void resize(double factor) {
        this.radius *= factor;
    }
}

// ── INTERFACE EXTENDING INTERFACE ─────────────────────────────────────────
interface Readable  { String read(); }
interface Writable  { void write(String s); }
interface ReadWrite extends Readable, Writable { }  // interface extends multiple interfaces

class FileStore implements ReadWrite {
    public String read()           { return "data"; }
    public void write(String s)    { /* persist */ }
}

// ── MAIN ──────────────────────────────────────────────────────────────────
public class Demo {
    public static void main(String[] args) {
        Circle c = new Circle("red", 5.0);
        c.draw();              // Drawing red circle, area=78.53...
        c.resize(2.0);
        c.draw();              // area is now larger
        System.out.println("Max sides constant: " + Config.MAX_SIDES); // 100
    }
}
