interface Flyer {
    default String move() { return "fly"; }
}

interface Swimmer {
    default String move() { return "swim"; }   // same default method name — clash!
}

class Duck implements Flyer, Swimmer {          // implementing many interfaces: OK

    // Compiler REQUIRES this override because both parents define move()
    @Override
    public String move() {
        // Explicitly pick a parent's default with InterfaceName.super.method()
        return Flyer.super.move() + "/" + Swimmer.super.move();  // "fly/swim"
    }
}

// Multiple interfaces — a class playing many roles at once
interface Comparable<T>  { int compareTo(T o); }
interface Printable      { void print(); }
interface Serializable   { }                    // marker: no methods at all

class Product implements Comparable<Product>, Printable, Serializable {
    private String name;
    private double price;

    Product(String name, double price) {
        this.name = name;
        this.price = price;
    }

    @Override public int compareTo(Product other) { return Double.compare(this.price, other.price); }
    @Override public void print() { System.out.println(name + " @ " + price); }
}

// This is illegal — Java will not compile it:
// class Duck extends Bird, Fish { }    // ERROR: multiple class inheritance not supported

public class Demo {
    public static void main(String[] args) {
        Duck duck = new Duck();
        System.out.println(duck.move());   // fly/swim

        Product p = new Product("Laptop", 999.99);
        p.print();                          // Laptop @ 999.99
    }
}
