// ── INTERFACE: capability, unrelated types can implement ─────────────────
interface Notifier {
    void send(String message);                     // contract
    default void sendWithTimestamp(String msg) {   // Java 8 default — shared helper
        send("[" + java.time.LocalTime.now() + "] " + msg);
    }
}

class EmailNotifier implements Notifier {
    @Override public void send(String msg) { System.out.println("EMAIL: " + msg); }
}

class SmsNotifier implements Notifier {
    @Override public void send(String msg) { System.out.println("SMS: " + msg); }
}

// Caller depends on the interface — swap implementations freely:
Notifier n = new EmailNotifier();
n.sendWithTimestamp("Order confirmed");    // [10:05:01] Order confirmed
n = new SmsNotifier();
n.sendWithTimestamp("Order shipped");      // [10:05:02] Order shipped


// ── ABSTRACT CLASS: shared state + template method ────────────────────────
abstract class Game {
    private String name;                           // shared instance field
    private int score;                             // shared instance field

    Game(String name) { this.name = name; }        // constructor

    // Template method: defines the algorithm, delegates the details
    public final void play() {
        start();
        score = computeScore();
        end();
    }

    abstract void start();                         // each game decides how it starts
    abstract int computeScore();                   // each game has its own scoring

    void end() {                                   // shared concrete: no need to repeat
        System.out.println(name + " finished. Score: " + score);
    }
}

class Chess extends Game {
    Chess() { super("Chess"); }
    @Override void start()         { System.out.println("Chess: setting up board"); }
    @Override int computeScore()   { return 42; }
}


// ── COMBINE: interface contract + abstract partial implementation ──────────
interface List<E> {                                // contract (simplified)
    E get(int index);
    int size();
    default boolean isEmpty() { return size() == 0; }  // default built on the contract
}

abstract class AbstractList<E> implements List<E> { // skeletal implementation
    // get() and size() still abstract — subclasses must provide these
    // other List methods can be built on top of get() and size() here
}

class SimpleList<E> extends AbstractList<E> {      // only fill the two gaps
    private Object[] data;
    private int count;
    SimpleList() { data = new Object[10]; }
    @Override public E get(int i)  { return (E) data[i]; }
    @Override public int size()    { return count; }
}


public class Demo {
    public static void main(String[] args) {
        Game chess = new Chess();
        chess.play();
        // Chess: setting up board
        // Chess finished. Score: 42
    }
}
